export interface ExperienceItem {
  company: string;
  location: string;
  role: string;
  date: string;
  link: string;
}

export interface PageItem {
  text: string;
  slug: string;
  showInNav: boolean;
  order: number;
}

export interface RedirectItem {
  slug: string;
  destination: string;
  linkrelme: boolean;
  slashToLink: boolean;
  social: boolean;
  socialNote?: string;
  username?: string;
  displayName?: string; // Override for platform name display (e.g., "Twitter/X" instead of "x")
  atproto?: boolean; // For ATProto/Bluesky IndieAuth support
}

export enum domainType {
  personal,
  project,
  work,
  business,
  other,
}

export type Domain = {
  name: string;
  type: domainType;
  icon?: React.ReactNode;
};

