              >
                <div className="flex size-12 shrink-0 items-center justify-center rounded-full bg-yellow-100 text-yellow-600 transition-colors group-hover:bg-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-400">
                  <Coffee size={24} />
                </div>
                <div>
                  <div
                    className="font-semibold text-zinc-800 dark:text-zinc-100"
                    style={{ fontFamily: "var(--font-balgin)" }}
                  >
                    Buy Me a Coffee
                  </div>
                  <div className="text-sm text-zinc-500 dark:text-zinc-400">
                    @jaspermayone
                  </div>
                </div>
              </Link>
            </div>

            <div className="mt-8 flex items-start gap-2 rounded-lg border border-zinc-200 bg-zinc-50 p-4 dark:border-zinc-700 dark:bg-zinc-800/30">
              <Heart
                size={18}
                className="mt-0.5 shrink-0 text-pink-500 dark:text-pink-400"
              />
              <p className="text-sm text-zinc-600 dark:text-zinc-400">
